import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { FaMapMarkerAlt, FaPhone, FaEnvelope, FaClock, FaFacebook, FaTwitter, FaInstagram, FaLinkedin, FaBuilding, FaUser, FaComments } from 'react-icons/fa';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { Textarea } from '../components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../components/ui/select';
import Footer from '../components/common/Footer';
import { toast } from 'sonner';

const ContactPage = () => {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        subject: '',
        message: ''
    });

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        toast.success("Message sent! We'll get back to you soon.");
        setFormData({ name: '', email: '', subject: '', message: '' });
    };

    const contactInfo = [
        {
            icon: <FaMapMarkerAlt className="text-2xl" />,
            title: "Our Office",
            content: "123 College Street, Near University Campus, Mumbai, Maharashtra 400001",
            secondary: "Visit us during business hours"
        },
        {
            icon: <FaPhone className="text-2xl" />,
            title: "Phone Numbers",
            content: "+91 98765 43210",
            secondary: "Mon-Fri: 9:00 AM - 6:00 PM"
        },
        {
            icon: <FaEnvelope className="text-2xl" />,
            title: "Email Support",
            content: "info@dormanddish.com",
            secondary: "support@dormanddish.com"
        },
        {
            icon: <FaClock className="text-2xl" />,
            title: "Working Hours",
            content: "Monday - Friday",
            secondary: "9:00 AM - 6:00 PM"
        }
    ];

    const socialLinks = [
        { icon: <FaFacebook className="text-xl" />, label: "Facebook", url: "#" },
        { icon: <FaTwitter className="text-xl" />, label: "Twitter", url: "#" },
        { icon: <FaInstagram className="text-xl" />, label: "Instagram", url: "#" },
        { icon: <FaLinkedin className="text-xl" />, label: "LinkedIn", url: "#" }
    ];

    return (
        <div className="min-h-screen bg-gradient-to-b from-[#FDF0D5] to-white">
            {/* Hero Section */}
            <section className="py-20 px-4 sm:px-6 lg:px-8">
                <div className="max-w-4xl mx-auto text-center">
                    <motion.div
                        initial={{ opacity: 0, y: -20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.6 }}
                    >
                        <h1 className="text-4xl sm:text-5xl font-bold text-[#0C3B2E] mb-6">
                            Contact <span className="text-[#6D9773]">Us</span>
                        </h1>
                        <p className="text-xl text-gray-700 max-w-3xl mx-auto mb-8">
                            Have questions or feedback? We'd love to hear from you. Reach out to us through any of the channels below.
                        </p>
                    </motion.div>
                </div>
            </section>

            {/* Contact Information Section */}
            <section className="py-16 px-4 sm:px-6 lg:px-8 bg-white/50">
                <div className="max-w-6xl mx-auto">
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.6 }}
                        className="text-center mb-12"
                    >
                        <h2 className="text-3xl font-bold text-[#0C3B2E] mb-4">Get in Touch</h2>
                        <p className="text-gray-600">We're here to help you with any questions or concerns</p>
                    </motion.div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                        {contactInfo.map((info, index) => (
                            <motion.div
                                key={index}
                                initial={{ opacity: 0, y: 20 }}
                                whileInView={{ opacity: 1, y: 0 }}
                                viewport={{ once: true }}
                                transition={{ duration: 0.6, delay: index * 0.1 }}
                                className="bg-white rounded-xl p-6 shadow-lg hover:shadow-xl transition-shadow duration-300 border border-[#6D9773]/20 text-center"
                            >
                                <div className="w-12 h-12 bg-[#6D9773]/10 rounded-lg flex items-center justify-center text-[#6D9773] mx-auto mb-4">
                                    {info.icon}
                                </div>
                                <h3 className="text-lg font-bold text-[#0C3B2E] mb-2">{info.title}</h3>
                                <p className="text-gray-700 mb-1 font-medium">{info.content}</p>
                                <p className="text-gray-500 text-sm">{info.secondary}</p>
                            </motion.div>
                        ))}
                    </div>
                </div>
            </section>

            {/* Contact Form Section */}
            <section className="py-20 px-4 sm:px-6 lg:px-8">
                <div className="max-w-6xl mx-auto">
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                        {/* Contact Form */}
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            whileInView={{ opacity: 1, x: 0 }}
                            viewport={{ once: true }}
                            transition={{ duration: 0.6 }}
                            className="bg-white rounded-xl p-8 shadow-lg border border-[#6D9773]/20"
                        >
                            <h3 className="text-2xl font-bold text-[#0C3B2E] mb-6 flex items-center">
                                <FaComments className="mr-3 text-[#6D9773]" />
                                Send us a Message
                            </h3>
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div>
                                        <Label className="mb-2 flex items-center">
                                            <FaUser className="mr-2 text-[#6D9773] text-sm" />
                                            Full Name
                                        </Label>
                                        <Input
                                            name="name"
                                            value={formData.name}
                                            onChange={handleInputChange}
                                            placeholder="Enter your full name"
                                            required
                                        />
                                    </div>
                                    <div>
                                        <Label className="mb-2 flex items-center">
                                            <FaEnvelope className="mr-2 text-[#6D9773] text-sm" />
                                            Email Address
                                        </Label>
                                        <Input
                                            type="email"
                                            name="email"
                                            value={formData.email}
                                            onChange={handleInputChange}
                                            placeholder="Enter your email"
                                            required
                                        />
                                    </div>
                                </div>
                                <div>
                                    <Label className="mb-2">Subject</Label>
                                    <Select
                                        value={formData.subject}
                                        onValueChange={(value) => setFormData(prev => ({ ...prev, subject: value }))}
                                    >
                                        <SelectTrigger>
                                            <SelectValue placeholder="Select a subject" />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="general">General Inquiry</SelectItem>
                                            <SelectItem value="support">Technical Support</SelectItem>
                                            <SelectItem value="business">Business Partnership</SelectItem>
                                            <SelectItem value="feedback">Feedback</SelectItem>
                                            <SelectItem value="report">Report an Issue</SelectItem>
                                        </SelectContent>
                                    </Select>
                                </div>
                                <div>
                                    <Label className="mb-2">Your Message</Label>
                                    <Textarea
                                        name="message"
                                        value={formData.message}
                                        onChange={handleInputChange}
                                        rows="6"
                                        placeholder="Tell us about your inquiry or feedback..."
                                        required
                                    />
                                </div>
                                <Button
                                    type="submit"
                                    className="w-full bg-[#6D9773] hover:bg-[#4A6F57] text-white py-3 rounded-lg font-semibold text-lg"
                                >
                                    Send Message
                                </Button>
                            </form>
                        </motion.div>

                        {/* Office Information */}
                        <motion.div
                            initial={{ opacity: 0, x: 20 }}
                            whileInView={{ opacity: 1, x: 0 }}
                            viewport={{ once: true }}
                            transition={{ duration: 0.6 }}
                            className="space-y-8"
                        >
                            <div className="bg-white rounded-xl p-8 shadow-lg border border-[#6D9773]/20">
                                <h3 className="text-2xl font-bold text-[#0C3B2E] mb-6 flex items-center">
                                    <FaBuilding className="mr-3 text-[#6D9773]" />
                                    Office Location
                                </h3>
                                <div className="space-y-4">
                                    <div className="flex items-start">
                                        <FaMapMarkerAlt className="text-[#6D9773] mt-1 mr-3 flex-shrink-0" />
                                        <div>
                                            <p className="font-semibold text-[#0C3B2E]">Headquarters</p>
                                            <p className="text-gray-700">123 College Street, Near University Campus</p>
                                            <p className="text-gray-700">Mumbai, Maharashtra 400001</p>
                                        </div>
                                    </div>
                                    <div className="flex items-start">
                                        <FaClock className="text-[#6D9773] mt-1 mr-3 flex-shrink-0" />
                                        <div>
                                            <p className="font-semibold text-[#0C3B2E]">Office Hours</p>
                                            <p className="text-gray-700">Monday - Friday: 9:00 AM - 6:00 PM</p>
                                            <p className="text-gray-700">Saturday: 10:00 AM - 2:00 PM</p>
                                            <p className="text-gray-700">Sunday: Closed</p>
                                        </div>
                                    </div>
                                </div>
                                
                                {/* Google Maps Placeholder */}
                                <div className="mt-6 bg-gray-200 rounded-lg h-64 flex items-center justify-center">
                                    <div className="text-center">
                                        <FaMapMarkerAlt className="text-4xl text-[#6D9773] mx-auto mb-2" />
                                        <p className="text-gray-600">Map Location</p>
                                        <p className="text-sm text-gray-500">123 College Street, Mumbai</p>
                                    </div>
                                </div>
                            </div>

                            {/* Social Media */}
                            <div className="bg-white rounded-xl p-6 shadow-lg border border-[#6D9773]/20">
                                <h3 className="text-xl font-bold text-[#0C3B2E] mb-4">Connect With Us</h3>
                                <p className="text-gray-600 mb-4">Follow us on social media for updates and news</p>
                                <div className="flex space-x-4">
                                    {socialLinks.map((social, index) => (
                                        <a
                                            key={index}
                                            href={social.url}
                                            className="w-10 h-10 bg-[#6D9773]/10 rounded-full flex items-center justify-center text-[#6D9773] hover:bg-[#6D9773] hover:text-white transition-colors duration-300"
                                            target="_blank"
                                            rel="noopener noreferrer"
                                        >
                                            {social.icon}
                                        </a>
                                    ))}
                                </div>
                            </div>
                        </motion.div>
                    </div>
                </div>
            </section>

            {/* FAQ Section */}
            <section className="py-16 px-4 sm:px-6 lg:px-8 bg-[#FDF0D5]/50">
                <div className="max-w-4xl mx-auto">
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.6 }}
                        className="text-center mb-12"
                    >
                        <h2 className="text-3xl font-bold text-[#0C3B2E] mb-4">Frequently Asked Questions</h2>
                        <p className="text-gray-600">Quick answers to common questions</p>
                    </motion.div>

                    <div className="space-y-6">
                        <div className="bg-white rounded-lg p-6 shadow-md border border-[#6D9773]/20">
                            <h3 className="text-lg font-bold text-[#0C3B2E] mb-2">How long does it take to get a response?</h3>
                            <p className="text-gray-700">We typically respond to inquiries within 24 hours during business days.</p>
                        </div>
                        <div className="bg-white rounded-lg p-6 shadow-md border border-[#6D9773]/20">
                            <h3 className="text-lg font-bold text-[#0C3B2E] mb-2">Do you offer 24/7 support?</h3>
                            <p className="text-gray-700">Yes, we offer emergency support through our dedicated hotline for urgent matters.</p>
                        </div>
                        <div className="bg-white rounded-lg p-6 shadow-md border border-[#6D9773]/20">
                            <h3 className="text-lg font-bold text-[#0C3B2E] mb-2">Can I schedule a meeting?</h3>
                            <p className="text-gray-700">Yes, you can schedule a meeting through our calendar system or by calling our office.</p>
                        </div>
                        <div className="bg-white rounded-lg p-6 shadow-md border border-[#6D9773]/20">
                            <h3 className="text-lg font-bold text-[#0C3B2E] mb-2">What information should I provide?</h3>
                            <p className="text-gray-700">Please provide your contact information, specific query, and any relevant details for faster resolution.</p>
                        </div>
                    </div>
                </div>
            </section>

            {/* Emergency Contact */}
            <section className="py-16 px-4 sm:px-6 lg:px-8 bg-gradient-to-r from-[#6D9773] to-[#4A6F57]">
                <div className="max-w-4xl mx-auto text-center">
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        whileInView={{ opacity: 1, y: 0 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.6 }}
                    >
                        <h2 className="text-3xl font-bold text-white mb-4">Emergency Contact</h2>
                        <p className="text-xl text-white/90 mb-8">
                            For urgent matters, please call our emergency hotline
                        </p>
                        <div className="bg-white/10 rounded-xl p-8 backdrop-blur-sm inline-block">
                            <FaPhone className="text-4xl text-white mx-auto mb-4" />
                            <p className="text-2xl font-bold text-white mb-2">+91 98765 43210</p>
                            <p className="text-white/80">Available 24/7 for emergencies</p>
                        </div>
                    </motion.div>
                </div>
</section>

<Footer />
</div>
);
};

export default ContactPage;